import { createServer } from "node:http";
import { readFile, stat, mkdir } from "node:fs/promises";
import { extname, join } from "node:path";
import { chromium } from "playwright-core";

const [root, outDir] = process.argv.slice(2);
const types = { ".html": "text/html", ".js": "text/javascript", ".css": "text/css", ".svg": "image/svg+xml", ".txt": "text/plain", ".woff2": "font/woff2", ".json": "application/json" };
const server = createServer(async (req, res) => {
  let path = join(root, decodeURIComponent(new URL(req.url, "http://x").pathname));
  try { if ((await stat(path)).isDirectory()) path = join(path, "index.html"); } catch { path += ".html"; }
  try { res.writeHead(200, { "Content-Type": types[extname(path)] ?? "application/octet-stream" }); res.end(await readFile(path)); }
  catch { res.writeHead(404); res.end("not found"); }
}).listen(4789);
await mkdir(outDir, { recursive: true });
const browser = await chromium.launch({ executablePath: "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome" });
const shots = [["overview", "/"], ["tender", "/tender/?doc=GVT000ETT26000101"]];
for (const [width, height, suffix] of [[1440, 900, "1440"], [390, 844, "390"]]) {
  const page = await browser.newPage({ viewport: { width, height }, deviceScaleFactor: 2 });
  const errors = [];
  page.on("pageerror", (e) => errors.push(e.message));
  page.on("console", (m) => m.type() === "error" && errors.push(m.text()));
  for (const [name, url] of shots) {
    await page.goto(`http://127.0.0.1:4789${url}`, { waitUntil: "networkidle" });
    await page.waitForTimeout(900);
    await page.screenshot({ path: join(outDir, `${name}-${suffix}.png`), fullPage: true });
  }
  if (width === 390) {
    await page.goto("http://127.0.0.1:4789/", { waitUntil: "networkidle" });
    await page.getByRole("button", { name: "Open menu" }).click();
    await page.waitForTimeout(500);
    await page.screenshot({ path: join(outDir, `menu-390.png`) });
  }
  if (errors.length) console.log(suffix, "errors:", errors);
  await page.close();
}
await browser.close();
server.close();
console.log("done");

import { createServer } from "node:http";
import { readFile, stat } from "node:fs/promises";
import { extname, join } from "node:path";
import { chromium } from "playwright-core";
const [root, outDir] = process.argv.slice(2);
const types = { ".html": "text/html", ".js": "text/javascript", ".css": "text/css", ".svg": "image/svg+xml", ".woff2": "font/woff2" };
const server = createServer(async (req, res) => {
  let path = join(root, decodeURIComponent(new URL(req.url, "http://x").pathname));
  try { if ((await stat(path)).isDirectory()) path = join(path, "index.html"); } catch { path += ".html"; }
  try { res.writeHead(200, { "Content-Type": types[extname(path)] ?? "application/octet-stream" }); res.end(await readFile(path)); } catch { res.writeHead(404); res.end(); }
}).listen(4789);
const browser = await chromium.launch({ executablePath: "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome" });
for (const [w, h] of [[1440, 900], [390, 844]]) {
  const page = await browser.newPage({ viewport: { width: w, height: h }, deviceScaleFactor: 2 });
  await page.route("http://127.0.0.1:4790/health", (r) => r.fulfill({ json: { ok: true, auth: true } }));
  await page.route("http://127.0.0.1:4790/auth", (r) => r.fulfill({ status: 401, json: { detail: "that access code is not valid" } }));
  await page.goto("http://127.0.0.1:4789/", { waitUntil: "networkidle" });
  await page.getByLabel("Access code").fill("wrong-code");
  await page.getByRole("button", { name: "Continue" }).click();
  await page.waitForTimeout(500);
  await page.screenshot({ path: join(outDir, `access-${w}.png`) });
  await page.close();
}
await browser.close(); server.close(); console.log("done");
