function SignIn() {
  const { signIn } = useKopi();
  const [code, setCode] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function submit(event: React.FormEvent) {
    event.preventDefault();
    setBusy(true);
    setError(null);
    try {
      await signIn(code.trim());
    } catch (e) {
      setError(e instanceof ApiError && e.status === 401 ? "That access code is not valid." : "Could not reach Kopi. Try again.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <Centered>
      <form onSubmit={submit} className="flex flex-col gap-6 rounded-xl bg-background p-8">
