export type ChipOption = { value: string; label: string; count?: number };

const ANY = "__any__";

/**
 * One filter as a chip: its name while unset, its value (tinted) once set. Opens a menu of
 * options with an "any" choice at the top that clears it.
 */
export function FilterChip({
  label,
  anyLabel,
  value,
  options,
  onChange,
  disabled,
}: {
  label: string;
  anyLabel: string;
  value: string | null;
  options: ChipOption[];
  onChange: (value: string | null) => void;
  disabled?: boolean;
}) {
  const selected = value ? (options.find((o) => o.value === value)?.label ?? value) : null;
  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        disabled={disabled}
        aria-label={selected ? `${label}: ${selected}. Change` : `Filter by ${label.toLowerCase()}`}
        className={cn(
          "inline-flex h-8 max-w-full items-center gap-1.5 rounded-full px-3.5 text-sm transition-colors outline-none focus-visible:ring-3 focus-visible:ring-ring/40 disabled:opacity-50",
