                {option.count !== undefined && <span className="text-xs text-muted-foreground tabular-nums">{option.count}</span>}
              </DropdownMenuRadioItem>
            ))}
          </DropdownMenuRadioGroup>
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
